const templates=[["Game Concept Brief","Structured starting point for a new game idea","Concept"],["Market Research Report","Competitor landscape, audience and opportunity","Research"],["Game Design Document","Core mechanics, systems, progression and experience","Design"],["Asset Production Brief","Asset requirements, style and technical constraints","Assets"],["Development Task","Implementation brief with acceptance criteria","Development"],["Devlog Script","Narrative structure for a development update","Marketing"],["QA Test Plan","Test cases, expected results and evidence","Quality"],["Post-Launch Feedback Report","Evidence-backed player issue analysis","Live Ops"]];
const initialTasks:Task[]=[{id:1,title:"Review controller movement architecture",department:"Game Development",priority:"High",done:false},{id:2,title:"Test sprint stamina tuning",department:"Game Development",priority:"Medium",done:false},{id:3,title:"Document camera polish settings",department:"Game Development",priority:"Low",done:true},{id:4,title:"Prepare environment asset references",department:"Asset Production",priority:"Medium",done:true}];

function App(){
const[active,setActive]=useState("Home"),[project,setProject]=useState<Project>(projects[0]),[projectMenu,setProjectMenu]=useState(false),[command,setCommand]=useState(""),[lastCommand,setLastCommand]=useState(""),[tasks,setTasks]=useState<Task[]>(initialTasks),[notice,setNotice]=useState(""),[showNotifications,setShowNotifications]=useState(false),[showTaskForm,setShowTaskForm]=useState(false),[newTask,setNewTask]=useState(""),[showProjectModal,setShowProjectModal]=useState(false),[period,setPeriod]=useState("This Month"),[uploadName,setUploadName]=useState(""),[selectedOps,setSelectedOps]=useState("Overview");
const notify=(s:string)=>{setNotice(s);window.setTimeout(()=>setNotice(""),2800)};
const submit=()=>{if(!command.trim())return;setLastCommand(command.trim());notify("Demo mode: command captured. AI execution will be connected in a later phase.");setCommand("")};
const addTask=()=>{if(!newTask.trim())return;setTasks(a=>[...a,{id:Date.now(),title:newTask.trim(),department:active==="Home"?"Studio Operations":active,priority:"Medium",done:false}]);setNewTask("");setShowTaskForm(false);notify("Demo task added to this session.")};
const openProject=(p:Project)=>{setProject(p);setActive("Project Workspace");setProjectMenu(false)};
const toggleTask=(id:number)=>setTasks(a=>a.map(t=>t.id===id?{...t,done:!t.done}:t));
return <div className="app-shell"><aside className="sidebar">
<div className="sidebar-scroll">
<div className="brand"><img className="brand-logo" src="/src/booski-logo.png" alt="Booski Studios" /></div>
<nav className="primary-nav">{nav.map(n=>{const I=n.icon;return <button key={n.label} className={`nav-item ${active===n.label?"active":""}`} onClick={()=>setActive(n.label)}><I size={18}/><span>{n.label}</span>{active===n.label&&<ChevronRight size={15} className="nav-chevron"/>}</button>})}</nav>
<div className="side-section"><div className="section-heading">PROJECTS <button onClick={()=>setShowProjectModal(true)}><Plus size={16}/></button></div>{projects.map(p=><button key={p.name} className={`project-link ${active==="Project Workspace"&&project.name===p.name?"selected":""}`} onClick={()=>openProject(p)}><img src={p.image} alt=""/><span><b>{p.name}</b><small>{p.type}</small></span></button>)}</div>
<div className="side-section knowledge"><div className="section-heading">KNOWLEDGE</div>{[["Game Library",Box],["Research",Search],["Templates",FileImage]].map(([label,I]:any)=><button className={`knowledge-link ${active===label?"selected-knowledge":""}`} key={label} onClick={()=>setActive(label)}><I size={16}/>{label}</button>)}</div>
<div className="side-section studio-tools"><div className="section-heading">STUDIO SYSTEMS</div>{studioNav.map(([label,I]:any)=><button className={`knowledge-link ${active===label?"selected-knowledge":""}`} key={label} onClick={()=>setActive(label)}><I size={16}/>{label}</button>)}</div>
</div>
<button className="profile" onClick={()=>setActive("Settings")}><div className="avatar">♛</div><span><b>Booski</b><small>Solo Developer</small></span><ChevronRight size={18}/></button></aside>
<main className="main-area"><header className="topbar"><div className="command-panel"><div className="command-input"><Sparkles size={18}/><input value={command} onChange={e=>setCommand(e.target.value)} onKeyDown={e=>e.key==="Enter"&&submit()} placeholder="Ask Booski anything or give it a task..."/><button className="send-button" onClick={submit}><Send size={20}/></button></div><div className="command-actions"><button onClick={()=>setCommand("Research ")}><Search size={14}/> Research</button><button onClick={()=>setCommand("Create ")}><WandSparkles size={14}/> Create</button><button onClick={()=>setCommand("Analyse ")}><Gauge size={14}/> Analyse</button><button onClick={()=>setCommand("Build ")}><Code2 size={14}/> Build</button><button onClick={()=>setCommand("Plan ")}><ListTodo size={14}/> Plan</button></div></div>
<div className="top-actions"><button className="icon-button" onClick={()=>setShowNotifications(!showNotifications)}><Bell size={19}/><i/></button><button className="icon-button" onClick={()=>setActive("Settings")}><Settings size={19}/></button><div className="mini-avatar">♛</div>{showNotifications&&<div className="notification-pop"><b>Notifications</b><p>No new notifications.</p><small>Demo interface</small></div>}</div></header>
<AnimatePresence mode="wait"><motion.div key={active} className="page-transition" initial={{opacity:0,y:9}} animate={{opacity:1,y:0}} exit={{opacity:0,y:-5}} transition={{duration:.2,ease:"easeOut"}}>{active==="Home"?<Home {...{project,projects,projectMenu,setProjectMenu,setProject,openProject,setActive,tasks,toggleTask,setShowTaskForm,period,setPeriod,notify}}/>:
active==="Project Workspace"?<ProjectWorkspace project={project} tasks={tasks} toggleTask={toggleTask} setActive={setActive} setShowTaskForm={setShowTaskForm} notify={notify}/>:
departments.some(d=>d.name===active)?<DepartmentPage key={active} name={active} project={project} notify={notify} setActive={setActive}/>:
active==="Studio Operations"?<StudioOperations selected={selectedOps} setSelected={setSelectedOps} notify={notify}/>:
active==="Game Library"?<GameLibrary openProject={openProject}/>:
active==="Research"?<ResearchPage uploadName={uploadName} setUploadName={setUploadName} notify={notify}/>:
active==="Templates"?<TemplatesPage notify={notify}/>:
active==="Agent Management"?<AgentManagement notify={notify}/>:
active==="Cost & Usage"?<CostUsage notify={notify}/>:
active==="Decision Log"?<DecisionLog/>:
active==="Approvals Centre"?<ApprovalsCentre notify={notify}/>:
active==="Integrations Hub"?<IntegrationsHub notify={notify}/>:
active==="Studio Knowledge"?<StudioKnowledge notify={notify}/>:
active==="Activity & Audit"?<ActivityAudit/>:
active==="Task Centre"?<TaskCentre tasks={tasks} toggleTask={toggleTask} setShowTaskForm={setShowTaskForm}/>:
<UtilityPage name={active} notify={notify}/>}</motion.div></AnimatePresence>
{showTaskForm&&<div className="modal-backdrop" onClick={()=>setShowTaskForm(false)}><div className="modal" onClick={e=>e.stopPropagation()}><button className="modal-close" onClick={()=>setShowTaskForm(false)}><X size={18}/></button><span className="eyebrow">TASK CENTRE</span><h2>Create a task</h2><p>Add a task to your local demo workspace.</p><input autoFocus value={newTask} onChange={e=>setNewTask(e.target.value)} onKeyDown={e=>e.key==="Enter"&&addTask()} placeholder="What needs doing?"/><div className="modal-actions"><button className="secondary-btn" onClick={()=>setShowTaskForm(false)}>Cancel</button><button className="primary-btn" onClick={addTask}>Add task</button></div></div></div>}
{showProjectModal&&<div className="modal-backdrop" onClick={()=>setShowProjectModal(false)}><div className="modal" onClick={e=>e.stopPropagation()}><button className="modal-close" onClick={()=>setShowProjectModal(false)}><X size={18}/></button><h2>New project</h2><p>Project creation will be connected to the persistent backend in a later phase.</p><button className="primary-btn" onClick={()=>setShowProjectModal(false)}>Got it</button></div></div>}
{lastCommand&&<div className="last-command"><Sparkles size={15}/> Last demo command: <b>{lastCommand}</b><button onClick={()=>setLastCommand("")}><X size={14}/></button></div>}{notice&&<div className="toast"><ShieldCheck size={16}/>{notice}</div>}
<footer>BOOSKI STUDIOS <span>•</span> FRONTEND FOUNDATION V0.4 <span>•</span> DEMO DATA — NOT CONNECTED TO LIVE SYSTEMS</footer></main></div>
}

function Home({project,projects,projectMenu,setProjectMenu,setProject,openProject,setActive,tasks,toggleTask,setShowTaskForm,period,setPeriod,notify}:any){
const done=tasks.filter((t:Task)=>t.done).length,pct=Math.round(done/Math.max(tasks.length,1)*100);
return <><div className="command-centre-heading"><div><span className="eyebrow">BOOSKI STUDIOS / COMMAND CENTRE</span><h1>Studio Command Centre</h1><p>Your studio at a glance. Coordinate projects, AI workers, decisions and approvals from one place.</p></div><span className="demo-chip">FRONTEND PREVIEW · DEMO DATA</span></div><section className="command-metrics"><div className="panel command-metric"><span className="metric-icon cyan"><FolderKanban size={18}/></span><small>Active projects</small><b>3</b><em>Across 2 development stages</em></div><div className="panel command-metric"><span className="metric-icon pink"><Bot size={18}/></span><small>Registered agents</small><b>6</b><em>Illustrative workforce</em></div><div className="panel command-metric"><span className="metric-icon green"><Workflow size={18}/></span><small>Tasks in progress</small><b>5</b><em>Sample workflow activity</em></div><div className="panel command-metric"><span className="metric-icon orange"><ShieldCheck size={18}/></span><small>Awaiting approval</small><b>3</b><em>Demo approval requests</em></div></section><section className="command-overview-grid"><article className="panel command-workforce"><div className="panel-title"><div><h2>AI Workforce</h2><small>Specialist agents across the studio</small></div><button onClick={()=>setActive("Agent Management")}>Manage agents <ArrowUpRight size={14}/></button></div><div className="workforce-strip">{[["Orchestrator","Coordinating",Network], ["Research Agent","Working",Search], ["Unity Agent","Working",Code2], ["Asset Agent","Available",Box], ["Marketing Agent","Available",Megaphone], ["Quality Agent","Reviewing",ShieldCheck]].map(([n,st,I]:any)=><div className="workforce-person"><span><I size={17}/></span><b>{n}</b><small>{st}</small></div>)}</div></article><article className="panel command-approvals"><div className="panel-title"><h2>Needs your attention</h2><button onClick={()=>setActive("Approvals Centre")}>View all <ArrowUpRight size={14}/></button></div>{[["Unity Agent","Review controller architecture changes","Game Development"],["Marketing Agent","Approve gameplay showcase script","Marketing Studio"],["Asset Agent","Approve environment asset direction","Asset Production"]].map(([a,b,c])=><div className="attention-row"><span className="attention-dot"/><div><b>{b}</b><small>{a} · {c}</small></div><ChevronRight size={15}/></div>)}</article></section><section className="department-grid">{departments.map(d=>{const I=d.icon;return <button key={d.name} className={`department-card ${d.color}`} style={{backgroundImage:`linear-gradient(90deg,rgba(3,10,20,.94),rgba(3,10,20,.55) 60%,rgba(3,10,20,.1)),url(${d.image})`}} onClick={()=>setActive(d.name)}><div className="department-icon"><I size={27}/></div><div className="department-copy"><b>{d.name}</b><p>{d.desc}</p></div><span className="department-arrow"><ArrowRight size={22}/></span></button>})}</section>
<section className="dashboard-grid top-grid"><article className="panel project-overview"><div className="panel-title"><h2>Project Overview</h2><div className="overview-select"><button onClick={()=>setProjectMenu(!projectMenu)}>{project.name}<ChevronDown size={14}/></button>{projectMenu&&<div className="overview-menu">{projects.map((p:Project)=><button key={p.name} onClick={()=>{setProject(p);setProjectMenu(false)}}>{p.name}</button>)}</div>}</div></div><div className="project-summary"><img src={project.image} alt=""/><div className="summary-copy"><b>{project.name}</b><div className="tags"><span>{project.status}</span><span>{project.type}</span><span>{project.engine}</span></div><p>{project.description}</p><div className="progress-line"><span style={{width:`${project.progress}%`}}/></div></div><strong>{project.progress}%</strong></div><div className="milestones">{["Core movement & interaction systems","Initial environment prototype","Asset style guide","Market analysis"].map((m,i)=><div key={m}><span className={`milestone-dot m${i}`}><Check size={13}/></span><span>{m}</span><small>{["3/5","Completed","2/4","Completed"][i]}</small></div>)}</div><button className="inline-link" onClick={()=>openProject(project)}>Open full project workspace <ArrowUpRight size={14}/></button></article>
<article className="panel focus-panel"><div className="panel-title"><h2>Current Focus</h2><button onClick={()=>setActive("Task Centre")}>View Tasks <ArrowUpRight size={14}/></button></div><div className="focus-card"><div className="focus-icon"><Gamepad2 size={22}/></div><div className="focus-content"><b>FPS Controller Package</b><div><span>Game Development</span><span className="priority">Next up</span></div><small>{done}/{tasks.length} demo tasks completed</small></div><div className="progress-ring" style={{background:`conic-gradient(#4bc8ec ${pct}%,#243447 0)`}}><span>{pct}%</span></div></div><div className="task-list">{tasks.slice(0,5).map((t:Task)=><button key={t.id} onClick={()=>toggleTask(t.id)}>{t.done?<CheckCircle2 className="task-done" size={18}/>:<Circle className="task-open" size={18}/>}<span className={t.done?"done":""}>{t.title}</span></button>)}</div><button className="inline-add" onClick={()=>setShowTaskForm(true)}><Plus size={14}/> Add task</button></article>
<article className="panel insights-panel"><div className="panel-title"><h2>Studio Insights</h2><select value={period} onChange={e=>setPeriod(e.target.value)}><option>This Month</option><option>This Week</option><option>This Year</option></select></div><div className="stats-grid">{[["Ideas Explored","12","+33%"],["Assets Generated","84","+120%"],["Hours Saved","38","+45%"],["Content Created","24","+80%"]].map(s=><div className="stat" key={s[0]}><small>{s[0]}</small><b>{s[1]}</b><em>↑ {s[2]}</em></div>)}</div><div className="chart-heading">Overall productivity <b>+120%</b></div><svg className="sparkline" viewBox="0 0 360 64" preserveAspectRatio="none"><path d="M0 51 C20 48 25 57 42 49 S68 39 83 46 S108 37 126 42 S151 24 169 34 S194 19 211 31 S236 12 253 23 S275 9 292 19 S321 9 337 17 S350 10 360 14" fill="none" stroke="#ff238c" strokeWidth="2.5"/></svg></article></section>
<section className="dashboard-grid bottom-grid"><article className="panel"><div className="panel-title"><h2>Recent Activity</h2><button onClick={()=>setActive("Task Centre")}>See all <ArrowUpRight size={14}/></button></div>{[[FileImage,"Generated forest environment assets","10 min ago"],[Code2,"Updated player controller system","1 hour ago"],[Clapperboard,"Created social media storyboard","2 hours ago"],[Search,"Researched competitor analysis","3 hours ago"]].map(([I,t,time]:any)=><div className="activity-row"><span className="activity-icon blue"><I size={16}/></span><span>{t}</span><small>{time}</small></div>)}</article><article className="panel"><div className="panel-title"><h2>Post-Launch Feedback</h2><button onClick={()=>setActive("Post-Launch Intelligence")}>View Details <ArrowUpRight size={14}/></button></div><div className="feedback-stats"><div><b className="pink-text">248</b><small>Total Feedback</small></div><div><b className="blue-text">37</b><small>Unique Issues</small></div><div><b className="orange-text">8</b><small>Need Review</small></div><div><b className="green-text">12</b><small>Positive Mentions</small></div></div><div className="feedback-row"><b>Audio positioning bug</b><span className="severity high">High</span><small>18 reports</small></div><div className="feedback-row"><b>Sprint stamina tuning</b><span className="severity medium">Medium</span><small>14 reports</small></div></article><article className="panel"><div className="panel-title"><h2>Latest Assets</h2><button onClick={()=>setActive("Asset Production")}>View All <ArrowUpRight size={14}/></button></div><div className="asset-grid">{[["Rock_Cliff_01","photo-1518837695005-2083093ee35b"],["Cabin_Wall_01","photo-1518005020951-eccb494ad742"],["Ambient_Forest","photo-1470225620780-dba8ba36b745"]].map(a=><div className="asset-card"><img src={`https://images.unsplash.com/${a[1]}?w=300&q=80`}/><b>{a[0]}</b></div>)}</div></article></section></>
}

function DepartmentPage({name,project,notify,setActive}:any){
const tabs=deptTabs[name],items=deptItems[name],queue=queueItems[name];
const[tab,setTab]=useState(tabs[0]),[query,setQuery]=useState(""),[selected,setSelected]=useState("");
const dept=departments.find(d=>d.name===name)!,I=dept.icon;
const filtered=items.filter(x=>x.title.toLowerCase().includes(query.toLowerCase()));
return <div className="workspace-page"><div className={`workspace-hero ${dept.color}`} style={{backgroundImage:`linear-gradient(90deg,rgba(4,12,22,.96),rgba(4,12,22,.72),rgba(4,12,22,.28)),url(${dept.image})`}}><div className="workspace-hero-top"><span className="eyebrow">BOOSKI STUDIOS / DEPARTMENTS</span><span className="demo-chip">DEMO WORKSPACE</span></div><div className="workspace-heading"><div className="workspace-icon"><I size={30}/></div><div><h1>{name}</h1><p>{dept.desc}</p></div></div><div className="workspace-actions">{(name==="Game Development"?["New development task","Inspect project"]:name==="Concept Lab"?["Start a new concept","Create research brief"]:name==="Asset Production"?["Create asset brief","Import assets"]:name==="Marketing Studio"?["Create content brief","Plan campaign"]:["Review feedback","Generate insight report"]).map((a,i)=><button className={i===0?"primary-btn":"secondary-btn"} onClick={()=>notify(`${a} will be connected to Booski AI Core in a later phase.`)}>{i===0?<Plus size={15}/>:<ArrowUpRight size={15}/>} {a}</button>)}</div></div>
<div className="workspace-tabs">{tabs.map(t=><button className={tab===t?"active-tab":""} key={t} onClick={()=>{setTab(t);setSelected("")}}>{t}</button>)}</div>
<div className="workspace-stats"><div><small>Department</small><b>{name}</b></div><div><small>Current project context</small><b>{project.name}</b></div><div><small>Workspace pulse</small><b className="green-text">Ready for setup</b></div><div><small>Department overview</small><b>{dept.metric}</b></div></div>
<div className="workspace-content-grid"><section className="panel workspace-main"><div className="panel-title"><h2>{tab}</h2><span className="demo-label">{tab===tabs[1]?"QUEUED WORK":"SAMPLE CONTENT"}</span></div>{tab===tabs[1]?<>{queue.map((q:any)=><div className="queue-item"><div className="queue-priority"><span className={`severity ${q.priority.toLowerCase()}`}>{q.priority}</span><small>{q.owner}</small></div><div className="queue-copy"><b>{q.title}</b><small>{q.detail}</small></div><button onClick={()=>notify(`Queue item selected: ${q.title}`)}><ChevronRight size={17}/></button></div>)}</>:tab==="Decision Log"?<DecisionLog initialDepartment={name}/>:tab===tabs[0]?<><div className="workspace-search"><Search size={16}/><input value={query} onChange={e=>setQuery(e.target.value)} placeholder={`Search ${name.toLowerCase()}...`}/></div>{filtered.map((w:any)=>{const W=w.icon;return <button className={`work-item ${selected===w.title?"selected-work":""}`} key={w.title} onClick={()=>setSelected(selected===w.title?"":w.title)}><span className="work-icon"><W size={19}/></span><span className="work-copy"><b>{w.title}</b><small>{w.detail}</small></span><span className="work-status">{w.status}</span><ChevronRight size={17}/></button>})}</>:<DepartmentTabContent name={name} tab={tab} notify={notify}/>}
{selected&&<div className="selected-detail"><b>{selected}</b><p>Demonstration item. Its full brief, linked files, history and AI recommendations will be available when connected to the backend.</p><button onClick={()=>notify(`Opened demo item: ${selected}`)}>Open details <ArrowUpRight size={14}/></button></div>}</section>
<aside className="panel workspace-side"><div className="panel-title"><h2>Department controls</h2></div><button className="quick-action" onClick={()=>notify("New work item will be created through Booski Core.")}><Plus size={15}/> Create new work</button><button className="quick-action" onClick={()=>notify("Agent assignment will be available after orchestration is connected.")}><Bot size={15}/> Assign AI agent</button><div className="side-divider"/><div className="panel-title"><h2>Department status</h2></div><div className="status-line"><span>Workspace</span><b className="green-text">Initialised</b></div><div className="status-line"><span>AI integration</span><b className="muted-text">Not connected</b></div><div className="status-line"><span>Data source</span><b className="muted-text">Demo content</b></div><button className="outline-wide" onClick={()=>setActive("Settings")}><Settings size={14}/> Configure integrations</button></aside></div></div>
}
function DepartmentTabContent({name,tab,notify}:any){
const mapping:Record<string,string[]>={"Concept Lab":["Research briefs and source-backed market reports will be stored here.","Concept scorecards, feasibility reviews and decision records."],"Game Development":["Build history, test runs, compilation results and verification evidence.","Architecture notes, API references, technical decisions and implementation docs."],"Asset Production":["Assets awaiting technical, visual or creative review.","Reusable generation, processing and import pipelines."],"Marketing Studio":["Planned campaigns, target platforms and publishing approvals.","Approved footage, scripts, thumbnails, audio and rendered exports."],"Post-Launch Intelligence":["Grouped reports from players, platforms and feedback channels.","Ranked issues with evidence, confidence, impact and estimated effort."]};
const idx=deptTabs[name].indexOf(tab),text=mapping[name]?.[Math.max(0,idx-1)]||"Department records and supporting information will appear here.";
return <div className="empty-work"><Layers size={27}/><b>{tab}</b><p>{text}</p><button className="secondary-btn" onClick={()=>notify(`${tab} tools will be connected in a later phase.`)}>Explore {tab}</button></div>
}
function ProjectWorkspace({project,tasks,toggleTask,setActive,setShowTaskForm,notify}:any){
const tabs=["Overview","Tasks","Design Documents","Assets","Reference Vault","Builds & Tests","Activity"],[tab,setTab]=useState("Overview");
return <div className="workspace-page"><div className="project-hero" style={{backgroundImage:`linear-gradient(90deg,rgba(4,12,22,.97),rgba(4,12,22,.72),rgba(4,12,22,.25)),url(${project.image})`}}><button className="back-link" onClick={()=>setActive("Home")}><ArrowLeft size={14}/> Dashboard</button><span className="demo-chip">PROJECT WORKSPACE · DEMO</span><h1>{project.name}</h1><p>{project.type} · {project.engine} project</p><div className="project-hero-bottom"><div><small>Development progress</small><b>{project.progress}%</b><div className="progress-line"><span style={{width:`${project.progress}%`}}/></div></div><button className="primary-btn" onClick={()=>notify("Engine connection will be handled by the Unity bridge phase.")}><Monitor size={15}/> Connect engine</button></div></div>
<div className="workspace-tabs">{tabs.map(t=><button className={tab===t?"active-tab":""} key={t} onClick={()=>setTab(t)}>{t}</button>)}</div><div className="workspace-stats"><div><small>Project status</small><b>{project.status}</b></div><div><small>Engine</small><b>{project.engine}</b></div><div><small>Open tasks</small><b>{tasks.filter((t:Task)=>!t.done).length}</b></div><div><small>Project context</small><b className="green-text">Isolated demo context</b></div></div>
<div className="workspace-content-grid"><section className="panel workspace-main"><div className="panel-title"><h2>{tab}</h2>{tab==="Tasks"&&<button onClick={()=>setShowTaskForm(true)}><Plus size={14}/> Add task</button>}</div>{tab==="Overview"? <><p className="project-description">{project.description} This project has its own dedicated context, documents, assets, references and development history.</p><div className="project-feature-grid">{[["Development tasks",`${tasks.length} tracked demo tasks`],["Design documents","Game design and technical docs"],["Assets","Linked project resources"],["Reference Vault","AI-discovered and user-saved references"],["Builds & tests","Engine verification history"]].map(([t,d])=><button key={t} onClick={()=>setTab(t==="Development tasks"?"Tasks":t==="Reference Vault"?"Reference Vault":t==="Assets"?"Assets":t==="Builds & tests"?"Builds & Tests":"Design Documents")}><BookOpen size={20}/><b>{t}</b><small>{d}</small></button>)}</div></>:tab==="Tasks"?tasks.map((t:Task)=><div className="task-record" key={t.id}><button className="task-toggle" onClick={()=>toggleTask(t.id)}>{t.done?<CheckCircle2 className="task-done" size={18}/>:<Circle className="task-open" size={18}/>}</button><span><b className={t.done?"done":""}>{t.title}</b><small>{t.department}</small></span><em className={`severity ${t.priority.toLowerCase()}`}>{t.priority}</em></div>):tab==="Reference Vault"?<ReferenceVault notify={notify}/>:<div className="empty-work"><Database size={28}/><b>{tab} workspace prepared</b><p>Project-specific {tab.toLowerCase()} and records will be connected to the backend.</p></div>}</section>
<aside className="panel workspace-side"><div className="panel-title"><h2>Project controls</h2></div><button className="quick-action" onClick={()=>notify("Project scan requires the Unity bridge.")}><Search size={15}/> Inspect project</button><button className="quick-action" onClick={()=>notify("Build and test execution requires the Unity bridge.")}><Play size={15}/> Run tests</button><button className="quick-action" onClick={()=>notify("Project backup will be connected to Git integration.")}><GitBranch size={15}/> Version control</button><div className="side-divider"/><div className="panel-title"><h2>Connection</h2></div><div className="status-line"><span>Unity editor</span><b className="muted-text">Not connected</b></div><div className="status-line"><span>Project memory</span><b className="green-text">Demo context</b></div></aside></div></div>
}
function ReferenceVault({notify}:any){return <div className="reference-vault"><div className="vault-toolbar"><p>References collected by Booski or saved by you for this project.</p><button className="primary-btn" onClick={()=>notify("Reference upload and URL capture will be connected to project storage.")}><Plus size={14}/> Add reference</button></div>{[["Visual direction","Low-poly abandoned research facility environment","AI discovered"],["Gameplay inspiration","First-person exploration and interaction reference","User saved"],["Lighting reference","Atmospheric corridor lighting and fog","AI discovered"]].map(([a,b,c])=><div className="reference-row"><span className="work-icon"><Image size={18}/></span><span><b>{a}</b><small>{b}</small></span><em>{c}</em><ExternalIcon/></div>)}</div>}
function ExternalIcon(){return <ArrowUpRight size={15} className="muted-text"/>}
function GameLibrary({openProject}:any){return <div className="workspace-page"><div className="simple-page-heading"><span className="eyebrow">BOOSKI STUDIOS / LIBRARY</span><h1>Game Library</h1><p>Your studio's games and prototypes, presented as a browsable library. Select a title to open its workspace.</p></div><div className="library-toolbar"><div className="workspace-search"><Search size={16}/><input placeholder="Search your library..."/></div><span>3 titles</span></div><div className="game-library-grid">{projects.map(p=><button className="game-library-card" key={p.name} onClick={()=>openProject(p)}><div className="library-cover"><img src={p.image} alt=""/><span>{p.status}</span></div><div className="library-info"><b>{p.name}</b><small>{p.type}</small><div className="library-progress"><span style={{width:`${p.progress}%`}}/></div><div><small>{p.engine} · {p.progress}% complete</small><ArrowUpRight size={15}/></div></div></button>)}</div></div>}
function ResearchPage({uploadName,setUploadName,notify}:any){return <div className="workspace-page"><div className="simple-page-heading"><span className="eyebrow">SHARED KNOWLEDGE / RESEARCH</span><h1>Research Library</h1><p>Source material and research documents produced by Booski during market research, plus your own uploaded research.</p></div><div className="research-actions"><label className="upload-button"><Upload size={16}/> Upload research<input type="file" accept=".pdf,.doc,.docx,.txt,.md,.csv,.xlsx,.pptx" onChange={e=>{const f=e.target.files?.[0];if(f){setUploadName(f.name);notify(`${f.name} selected. File storage will be connected in the backend phase.`)}}}/></label><span>{uploadName?`Selected: ${uploadName}`:"Supported: PDF, DOCX, TXT, MD, CSV, XLSX, PPTX"}</span></div><div className="research-grid">{[["Indie Horror Market Landscape","Market research · 18 sources · 04 Nov 2026","PDF"],["First-Person Horror Competitor Review","Competitor analysis · 12 games · 02 Nov 2026","DOCX"],["Audience & Steam Tag Analysis","Audience research · 9 sources · 29 Oct 2026","PDF"],["Survival Game Pricing Benchmarks","Pricing research · 15 sources · 26 Oct 2026","XLSX"]].map(([a,b,c])=><article className="panel research-card"><div className="research-file-icon"><FileText size={22}/></div><div><b>{a}</b><small>{b}</small></div><span>{c}</span><button onClick={()=>notify(`Opening ${a} is a future file-library capability.`)}><ArrowUpRight size={15}/></button></article>)}</div><p className="small-note">Sample research entries are illustrative. Uploaded files are not yet persisted or processed in this prototype.</p></div>}
function TemplatesPage({notify}:any){return <div className="workspace-page"><div className="simple-page-heading"><span className="eyebrow">SHARED KNOWLEDGE / TEMPLATES</span><h1>Template Library</h1><p>Reusable studio documents that Booski can duplicate and populate when starting new work.</p></div><div className="template-toolbar"><div className="workspace-search"><Search size={16}/><input placeholder="Search templates..."/></div><button className="secondary-btn" onClick={()=>notify("Adding custom templates will be supported by the file library.")}><Upload size={14}/> Add template</button></div><div className="template-grid">{templates.map(([a,b,c])=><article className="panel template-card"><div className="template-card-top"><span className="work-icon"><FileText size={19}/></span><span className="template-category">{c}</span></div><b>{a}</b><p>{b}</p><div><button className="secondary-btn" onClick={()=>notify(`Previewing ${a} template.`)}>Preview</button><button className="primary-btn" onClick={()=>notify(`Booski would duplicate ${a} and use the copy as a working document.`)}><CopyIcon/> Use template</button></div></article>)}</div></div>}
function CopyIcon(){return <Layers size={14}/>}
function StudioOperations({selected,setSelected,notify}:any){
const agents=[{name:"Orchestrator",role:"Task routing & coordination",x:50,y:9,tasks:["Breaking down incoming requests","Assigning work to specialist agents"]},{name:"Research Agent",role:"Research & evidence gathering",x:13,y:43,tasks:["Collecting competitor references","Preparing market landscape report"]},{name:"Unity Agent",role:"Game development",x:38,y:43,tasks:["Reviewing FPS controller architecture","Preparing regression test plan"]},{name:"Asset Agent",role:"Asset production",x:63,y:43,tasks:["Preparing environment asset brief","Checking import requirements"]},{name:"Marketing Agent",role:"Content production",x:88,y:43,tasks:["Drafting development update outline"]},{name:"Quality Agent",role:"Review & verification",x:50,y:78,tasks:["Checking task acceptance criteria","Reviewing evidence before completion"]}];
const ops=["Overview","Projects & Roadmaps","Tasks & Milestones","Studio Calendar"];
const [hover,setHover]=useState<string|null>(null),[pan,setPan]=useState({x:0,y:0});
const drag=useRef<{pointerId:number;startX:number;startY:number;originX:number;originY:number}|null>(null);
const active=agents.find(a=>a.name===hover);
const startPan=(e:any)=>{if(e.button!==0)return;drag.current={pointerId:e.pointerId,startX:e.clientX,startY:e.clientY,originX:pan.x,originY:pan.y};e.currentTarget.setPointerCapture(e.pointerId);};
const movePan=(e:any)=>{if(!drag.current||drag.current.pointerId!==e.pointerId)return;setPan({x:drag.current.originX+e.clientX-drag.current.startX,y:drag.current.originY+e.clientY-drag.current.startY});};
const stopPan=(e:any)=>{if(drag.current?.pointerId===e.pointerId)drag.current=null;};
return <div className="workspace-page"><div className="simple-page-heading"><span className="eyebrow">BOOSKI STUDIOS / MANAGEMENT</span><h1>Studio Operations</h1><p>Manage studio priorities, projects and schedules, and see how AI capabilities coordinate work across departments.</p></div><div className="operations-layout"><aside className="panel operations-menu"><div className="panel-title"><h2>Studio management</h2></div>{ops.map((o,i)=>{const OpIcon=[Compass,FolderKanban,ListTodo,CalendarDays][i];return <button key={o} className={selected===o?"ops-active":""} onClick={()=>setSelected(o)}><span><OpIcon size={16}/></span>{o}<ChevronRight size={14}/></button>})}<div className="side-divider"/><div className="status-line"><span>Agents registered</span><b>6 demo agents</b></div><div className="status-line"><span>Running tasks</span><b className="green-text">5 demo tasks</b></div></aside><section className="panel operations-canvas-panel"><div className="panel-title"><div><h2>{selected==="Overview"?"AI Workforce & Live Workflow":selected}</h2><small className="canvas-subtitle">Illustrative agent activity · Not connected to live execution</small></div><span className="live-pill"><i/> DEMO LIVE VIEW</span></div>{selected==="Overview"?<><div className="canvas-instructions"><span>↔ Drag to move around the canvas</span><span>Hover an agent to inspect its current tasks</span></div><div className="agent-canvas" onPointerDown={startPan} onPointerMove={movePan} onPointerUp={stopPan} onPointerCancel={stopPan} onLostPointerCapture={stopPan} style={{cursor:drag.current?"grabbing":"grab",touchAction:"none"}}><div className="agent-canvas-world" style={{transform:`translate(${pan.x}px, ${pan.y}px)`}}><svg viewBox="0 0 100 100" preserveAspectRatio="none"><defs><marker id="arrow" markerWidth="4" markerHeight="4" refX="3" refY="2" orient="auto"><path d="M0 0 L4 2 L0 4" fill="#47cce9"/></marker></defs><defs><filter id="flowGlow" x="-50%" y="-50%" width="200%" height="200%"><feGaussianBlur stdDeviation=".75" result="blur"/><feMerge><feMergeNode in="blur"/><feMergeNode in="SourceGraphic"/></feMerge></filter><linearGradient id="flowGradient"><stop offset="0%" stopColor="#f52a9b"/><stop offset="55%" stopColor="#55d9f1"/><stop offset="100%" stopColor="#a6f47b"/></linearGradient></defs>
{["M50 18 C42 24 22 27 13 40","M50 18 C48 25 40 29 38 40","M50 18 C53 25 61 29 63 40","M50 18 C61 23 81 28 88 40"].map((d,i)=><motion.path key={i} d={d} stroke="url(#flowGradient)" strokeWidth=".65" fill="none" filter="url(#flowGlow)" strokeLinecap="round" strokeDasharray="2 1.5" animate={{strokeDashoffset:[0,-14],opacity:[.65,1,.65]}} transition={{duration:2.2+i*.35,repeat:Infinity,ease:"linear"}}/>)}
{["M13 52 C17 67 36 68 50 76","M38 52 C39 65 45 69 50 76","M63 52 C61 65 55 69 50 76","M88 52 C83 67 64 68 50 76"].map((d,i)=><motion.path key={`back-${i}`} d={d} stroke="#4b9bb9" strokeWidth=".42" fill="none" opacity=".55" strokeDasharray="1 2" animate={{strokeDashoffset:[0,12]}} transition={{duration:3+i*.3,repeat:Infinity,ease:"linear"}}/>)}</svg>{agents.map((a,i)=><motion.div key={a.name} initial={{opacity:0}} animate={{opacity:1}} transition={{delay:i*.07,duration:.25}} className={`agent-node node-${i} ${hover===a.name?"agent-hover":""}`} style={{left:`${a.x}%`,top:`${a.y}%`}} onPointerEnter={()=>setHover(a.name)} onPointerLeave={()=>setHover(null)} onFocus={()=>setHover(a.name)} onBlur={()=>setHover(null)} tabIndex={-1}><span className="agent-node-icon">{i===0?<Network size={18}/>:i===1?<Search size={18}/>:i===2?<Code2 size={18}/>:i===3?<Box size={18}/>:i===4?<Megaphone size={18}/>:<ShieldCheck size={18}/>}</span><b>{a.name}</b><small>{a.role}</small><i/></motion.div>)}</div>{active&&<motion.div className="agent-detail" initial={{opacity:0,x:8}} animate={{opacity:1,x:0}} exit={{opacity:0}} key={active.name}><span className="eyebrow">CURRENT TASKS</span><b>{active.name}</b><small>{active.role}</small><ul>{active.tasks.map(t=><li key={t}>{t}</li>)}</ul></motion.div>}<div className="canvas-legend"><span><i className="legend-dot green-dot"/> Working</span><span><i className="legend-dot blue-dot"/> Coordinating</span><span><i className="legend-dot grey-dot"/> Awaiting input</span></div></div></>:<div className="ops-detail"><div className="empty-work"><Workflow size={30}/><b>{selected}</b><p>This management area will display live studio records once the Booski Core database and workflows are connected.</p><button className="secondary-btn" onClick={()=>notify(`${selected} workspace is prepared for backend integration.`)}>Open workspace</button></div></div>}</section></div></div>
}
function TaskCentre({tasks,toggleTask,setShowTaskForm}:any){return <div className="workspace-page"><div className="simple-page-heading"><span className="eyebrow">STUDIO OPERATIONS</span><h1>Task Centre</h1><p>One place to review and manage work across the studio.</p></div><section className="panel task-centre">{tasks.map((t:Task)=><div className="task-record"><button className="task-toggle" onClick={()=>toggleTask(t.id)}>{t.done?<CheckCircle2 size={18} className="task-done"/>:<Circle size={18} className="task-open"/>}</button><span><b className={t.done?"done":""}>{t.title}</b><small>{t.department}</small></span><em className={`severity ${t.priority.toLowerCase()}`}>{t.priority}</em></div>)}<button className="primary-btn" onClick={()=>setShowTaskForm(true)}><Plus size={14}/> New task</button></section></div>}

const agentRecords=[{name:"Orchestrator",role:"Task routing & coordination",department:"Studio-wide",status:"Coordinating",work:"Breaking requests into tasks and assigning specialist agents",model:"Claude",permissions:"Read · Create · Route",cost:"Shared"},{name:"Research Agent",role:"Market & reference research",department:"Concept Lab",status:"Working",work:"Preparing indie horror market landscape",model:"Claude",permissions:"Read · Create",cost:"Tracked per task"},{name:"Unity Agent",role:"Unity development specialist",department:"Game Development",status:"Working",work:"Reviewing FPS controller architecture",model:"Claude Code",permissions:"Read · Create · Modify · Execute (approval)",cost:"Tracked per task"},{name:"Asset Agent",role:"Asset creation & pipeline support",department:"Asset Production",status:"Available",work:"No active assignment",model:"Configurable",permissions:"Read · Create",cost:"Tracked per task"},{name:"Marketing Agent",role:"Marketing & content production",department:"Marketing Studio",status:"Available",work:"No active assignment",model:"Configurable",permissions:"Read · Create · Publish (approval)",cost:"Tracked per task"},{name:"Quality Agent",role:"Review, testing & verification",department:"Studio-wide",status:"Reviewing",work:"Checking acceptance criteria and evidence",model:"Configurable",permissions:"Read · Execute (approval)",cost:"Tracked per task"}];
function PageHeading({eyebrow,title,description}:any){return <div className="simple-page-heading"><span className="eyebrow">{eyebrow}</span><h1>{title}</h1><p>{description}</p><span className="demo-chip">DEMO DATA · NOT CONNECTED TO LIVE SERVICES</span></div>}
function AgentManagement({notify}:any){return <div className="workspace-page"><PageHeading eyebrow="BOOSKI AI CORE / WORKFORCE" title="Agent Management" description="Manage the specialist AI workforce, review responsibilities and understand which tools and permissions each agent can use."/><div className="agent-management-grid">{agentRecords.map((a,i)=><article className="panel managed-agent"><div className="managed-agent-top"><span className="work-icon"><Bot size={20}/></span><span className={`agent-status ${a.status.toLowerCase()}`}>{a.status}</span></div><h3>{a.name}</h3><p>{a.role}</p><div className="agent-meta"><small>Department</small><b>{a.department}</b><small>Assigned work</small><span>{a.work}</span><small>Model</small><b>{a.model}</b><small>Permissions</small><span>{a.permissions}</span></div><button className="secondary-btn" onClick={()=>notify(`${a.name} configuration will be editable when the agent registry is connected.`)}>Configure agent <ArrowUpRight size={14}/></button></article>)}</div></div>}
function CostUsage({notify}:any){const usage=[{name:"Concept",tokens:18,cost:3.2},{name:"Development",tokens:42,cost:8.4},{name:"Assets",tokens:25,cost:5.1},{name:"Marketing",tokens:12,cost:2.4},{name:"Post-launch",tokens:9,cost:1.8}];const trend=[{period:"W1",cost:3.2},{period:"W2",cost:4.8},{period:"W3",cost:6.1},{period:"W4",cost:6.8}];return <div className="workspace-page"><PageHeading eyebrow="BOOSKI AI CORE / FINANCIALS" title="Cost & Usage" description="Understand AI consumption and operating costs across providers, agents, workflows and projects."/><div className="demo-chart-note"><span className="demo-label">ILLUSTRATIVE DATA</span> Charts demonstrate the intended reporting layout; they are not actual provider charges or usage.</div><div className="usage-summary-grid">{[["Estimated monthly spend","£22.50","Illustrative sample only"],["Model usage","106k tokens","Illustrative sample only"],["API usage","5 workflows","Illustrative sample only"],["Budget status","Not configured","Set limits before automation"]].map(([a,b,c])=><article className="panel usage-summary"><small>{a}</small><b>{b}</b><span>{c}</span></article>)}</div><div className="usage-columns"><section className="panel"><div className="panel-title"><h2>Usage by department</h2><span className="demo-label">SAMPLE</span></div><div className="chart-wrap"><ResponsiveContainer width="100%" height={230}><BarChart data={usage} margin={{top:8,right:8,left:-18,bottom:5}}><CartesianGrid stroke="#1c3a50" strokeDasharray="3 3" vertical={false}/><XAxis dataKey="name" tick={{fill:"#9bb0c2",fontSize:10}} axisLine={false} tickLine={false}/><YAxis tick={{fill:"#8199ad",fontSize:9}} axisLine={false} tickLine={false}/><Tooltip contentStyle={{background:"#071725",border:"1px solid #31536b",borderRadius:8,color:"#fff"}}/><Bar dataKey="tokens" name="Usage (k tokens)" fill="#42cce7" radius={[5,5,0,0]}/></BarChart></ResponsiveContainer></div></section><section className="panel"><div className="panel-title"><h2>Illustrative weekly spend</h2><span className="demo-label">SAMPLE</span></div><div className="chart-wrap"><ResponsiveContainer width="100%" height={230}><AreaChart data={trend} margin={{top:8,right:8,left:-18,bottom:5}}><defs><linearGradient id="costFill" x1="0" y1="0" x2="0" y2="1"><stop offset="0%" stopColor="#ed329b" stopOpacity={.38}/><stop offset="100%" stopColor="#ed329b" stopOpacity={0}/></linearGradient></defs><CartesianGrid stroke="#1c3a50" strokeDasharray="3 3" vertical={false}/><XAxis dataKey="period" tick={{fill:"#9bb0c2",fontSize:10}} axisLine={false} tickLine={false}/><YAxis tick={{fill:"#8199ad",fontSize:9}} axisLine={false} tickLine={false}/><Tooltip contentStyle={{background:"#071725",border:"1px solid #31536b",borderRadius:8,color:"#fff"}} formatter={(v:any)=>[`£${Number(v).toFixed(2)}`,"Spend"]}/><Area type="monotone" dataKey="cost" stroke="#f34aa9" strokeWidth={2} fill="url(#costFill)"/></AreaChart></ResponsiveContainer></div></section></div><div className="panel budget-controls"><div className="panel-title"><h2>Budget controls</h2></div><p className="muted-copy">Set monthly limits, per-agent spending thresholds and approval requirements before connecting paid providers.</p><button className="primary-btn" onClick={()=>notify("Budget settings will be persisted in Booski Core.")}>Configure budgets <SlidersHorizontal size={14}/></button></div></div>}
function DecisionLog({initialDepartment}:any={}){const [filter,setFilter]=useState(initialDepartment||"All departments");const rows=[{date:"04 Nov 2026 · 14:32",decision:"Keep Booski Core model-provider agnostic",department:"Studio Operations",agent:"Architecture Agent",type:"Architecture",reason:"Avoid locking orchestration and future workflows to a single model provider."},{date:"04 Nov 2026 · 12:10",decision:"Use a single central Decision Log with contextual filters",department:"Studio Operations",agent:"Orchestrator",type:"Product",reason:"Maintain one source of truth while allowing department-level views."},{date:"03 Nov 2026 · 16:45",decision:"Unity is the first supported engine integration",department:"Game Development",agent:"Unity Agent",type:"Technical",reason:"Prioritise the existing Unity workflow before adding Unreal support."},{date:"02 Nov 2026 · 11:20",decision:"Separate project knowledge from studio-wide knowledge",department:"Concept Lab",agent:"Research Agent",type:"Knowledge",reason:"Prevent project-specific assumptions becoming universal studio rules."}];const visible=filter==="All departments"?rows:rows.filter(r=>r.department===filter);return <div className="workspace-page"><PageHeading eyebrow="BOOSKI AI CORE / GOVERNANCE" title="Decision Log" description="A searchable record of important decisions, who made or recommended them, the context and the reasoning behind them."/><div className="panel decision-panel"><div className="decision-toolbar"><span>{visible.length} recorded decisions</span><select value={filter} onChange={e=>setFilter(e.target.value)}><option>All departments</option>{["Studio Operations","Game Development","Concept Lab","Asset Production","Marketing Studio","Post-Launch Intelligence"].map(d=><option>{d}</option>)}</select></div>{visible.map(r=><article className="decision-row"><div className="decision-date">{r.date}</div><div className="decision-main"><b>{r.decision}</b><p>{r.reason}</p><div className="decision-tags"><span>{r.department}</span><span>{r.agent}</span><span>{r.type}</span></div></div><ChevronRight size={16}/></article>)}</div><p className="small-note">Sample entries illustrate the intended structure. Future records will distinguish AI recommendations, human approvals and final studio decisions.</p></div>}
function ApprovalsCentre({notify}:any){const approvals=[["Unity Agent","Review controller architecture changes","Game Development","File modification"],["Marketing Agent","Approve gameplay showcase script","Marketing Studio","Content approval"],["Asset Agent","Approve environment asset direction","Asset Production","Creative approval"]];return <div className="workspace-page"><PageHeading eyebrow="BOOSKI AI CORE / GOVERNANCE" title="Approvals Centre" description="A single review queue for actions that need your permission before an agent proceeds."/><div className="panel approvals-list">{approvals.map(([a,b,c,d])=><div className="approval-row"><span className="work-icon"><ShieldCheck size={19}/></span><div><b>{b}</b><small>{a} · {c} · {d}</small></div><button className="secondary-btn" onClick={()=>notify("Approval details are demo-only until workflow execution is connected.")}>Review</button></div>)}</div><p className="small-note">No action is actually approved or executed in this frontend preview.</p></div>}
function IntegrationsHub({notify}:any){const integrations=[["Unity","Game engine","Not connected"],["Unreal Engine","Game engine","Planned"],["GitHub","Version control","Not connected"],["Blender","3D asset production","Not connected"],["Steam","Player reviews","Not connected"],["Discord","Community feedback","Not connected"],["YouTube","Video & comments","Not connected"],["Claude Code","AI development tooling","Not connected"]];return <div className="workspace-page"><PageHeading eyebrow="BOOSKI AI CORE / CONNECTIONS" title="Integrations Hub" description="Connect the tools and platforms used across the studio, then control which agents can access each connection."/><div className="integration-grid">{integrations.map(([a,b,c])=><article className="panel integration-card"><div className="integration-mark"><Network size={19}/></div><div><b>{a}</b><small>{b}</small></div><span>{c}</span><button className="secondary-btn" onClick={()=>notify(`${a} connection setup will be handled in the integration phase.`)}>{c==="Planned"?"Planned":"Configure"}</button></article>)}</div></div>}
function StudioKnowledge({notify}:any){const docs=[["Studio Identity & Brand Guide","Studio-wide · Brand and communication standards","Studio-wide"],["AI Working Principles","Studio-wide · Approval boundaries and operating principles","Studio-wide"],["Unity Development Standards","Game Development · Coding and project conventions","Game Development"],["Mournforge Design Direction","Mournforge · World, tone and art direction","Concept Lab"],["Marketing Voice & Style","Marketing Studio · Tone, formats and publishing guidelines","Marketing Studio"]];return <div className="workspace-page"><PageHeading eyebrow="BOOSKI AI CORE / KNOWLEDGE" title="Studio Knowledge Base" description="Shared studio knowledge alongside project-specific documentation. Agents retrieve relevant context without mixing unrelated project decisions."/><div className="knowledge-scope-grid"><article className="panel"><span className="eyebrow">SHARED KNOWLEDGE</span><h2>Studio-wide foundations</h2><p>Brand identity, working practices, technical standards and reusable lessons.</p></article><article className="panel"><span className="eyebrow">PROJECT KNOWLEDGE</span><h2>Isolated project context</h2><p>Game-specific designs, decisions, references, architecture and production notes.</p></article></div><div className="panel knowledge-doc-list">{docs.map(([a,b,c])=><div className="knowledge-doc"><span className="work-icon"><BookOpen size={18}/></span><div><b>{a}</b><small>{b}</small></div><span>{c}</span><button onClick={()=>notify(`Opening ${a} requires the connected knowledge store.`)}><ArrowUpRight size={15}/></button></div>)}</div></div>}
function ActivityAudit(){const rows=[["Unity Agent","Reviewed FPS controller architecture","Game Development","Today · 14:32"],["Research Agent","Prepared indie horror market scan","Concept Lab","Today · 12:10"],["Asset Agent","Collected coastal environment references","Asset Production","Yesterday · 16:45"],["Marketing Agent","Drafted gameplay showcase outline","Marketing Studio","Yesterday · 11:20"],["Orchestrator","Routed new work to specialist agents","Studio Operations","02 Nov · 09:15"]];return <div className="workspace-page"><PageHeading eyebrow="BOOSKI AI CORE / TRACEABILITY" title="Activity & Audit" description="A chronological record of agent activity, task changes, file operations and approvals. This is the foundation for investigating and recovering from problems."/><div className="panel audit-list">{rows.map(([a,b,c,d])=><div className="audit-row"><span className="audit-mark"><Clock3 size={16}/></span><div><b>{b}</b><small>{a} · {c}</small></div><time>{d}</time></div>)}</div><p className="small-note">Illustrative records only. Live audit events will be written by Booski Core and retained according to configurable policies.</p></div>}

function UtilityPage({name,notify}:any){const desc:Record<string,string>={Settings:"Configure AI providers, integrations, permissions, notifications and studio preferences."};return <div className="workspace-page"><div className="simple-page-heading"><span className="eyebrow">BOOSKI STUDIOS</span><h1>{name}</h1><p>{desc[name]||"A shared workspace for the Booski Studios operating system."}</p></div><div className="utility-grid">{[["AI providers","Choose and configure model providers"],["Integrations","Unity, GitHub, MCP servers and external APIs"],["Permissions","Approval rules and action boundaries"],["Appearance","Branding, theme and interface preferences"]].map(([a,b])=><button className="panel utility-card" onClick={()=>notify(`${a} will be configured when the backend is connected.`)}><span className="work-icon"><Settings size={19}/></span><b>{a}</b><small>{b}</small><ArrowUpRight size={16}/></button>)}</div></div>}
export default App;
